/** A node in the recency list. */
interface Entry<K, V> {
  key: K;
  value: V;
  prev: Entry<K, V> | null;
  next: Entry<K, V> | null;
}

/**
 * A fixed-capacity least-recently-used cache.
 *
 * Backed by a hash map plus a doubly linked recency list, so lookups,
 * insertions, overwrites, evictions and removals all run in O(1) expected
 * time. Both {@link get} and {@link set} mark the key as most recently used.
 */
export class LruCache<K, V> {
  readonly capacity: number;
  readonly #entries = new Map<K, Entry<K, V>>();
  /** Least recently used entry. */
  #head: Entry<K, V> | null = null;
  /** Most recently used entry. */
  #tail: Entry<K, V> | null = null;

  constructor(capacity: number) {
    if (!Number.isSafeInteger(capacity) || capacity < 1) {
      throw new RangeError(`capacity must be a positive integer: ${capacity}`);
    }
    this.capacity = capacity;
  }

  get size(): number {
    return this.#entries.size;
  }

  /** Returns the value for `key`, or `undefined` if absent; a hit refreshes recency. */
  get(key: K): V | undefined {
    const entry = this.#entries.get(key);
    if (entry === undefined) return undefined;
    this.#moveToTail(entry);
    return entry.value;
  }

  /** Inserts or overwrites `key`, making it most recently used and evicting if over capacity. */
  set(key: K, value: V): void {
    const existing = this.#entries.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.#moveToTail(existing);
      return;
    }
    const entry: Entry<K, V> = { key, value, prev: null, next: null };
    this.#entries.set(key, entry);
    this.#append(entry);
    if (this.#entries.size > this.capacity) {
      const eldest = this.#head!;
      this.#unlink(eldest);
      this.#entries.delete(eldest.key);
    }
  }

  /** Removes `key`; returns `true` if it was present. */
  delete(key: K): boolean {
    const entry = this.#entries.get(key);
    if (entry === undefined) return false;
    this.#unlink(entry);
    this.#entries.delete(key);
    return true;
  }

  #moveToTail(entry: Entry<K, V>): void {
    if (entry === this.#tail) return;
    this.#unlink(entry);
    this.#append(entry);
  }

  #append(entry: Entry<K, V>): void {
    entry.prev = this.#tail;
    entry.next = null;
    if (this.#tail === null) this.#head = entry;
    else this.#tail.next = entry;
    this.#tail = entry;
  }

  #unlink(entry: Entry<K, V>): void {
    const { prev, next } = entry;
    if (prev === null) this.#head = next;
    else prev.next = next;
    if (next === null) this.#tail = prev;
    else next.prev = prev;
    entry.prev = null;
    entry.next = null;
  }
}

/**
 * Reads a capacity followed by cache commands from standard input and writes
 * command results to standard output, one per line.
 */
import { LruCache } from './lru-cache.ts';

const OUTPUT_FLUSH_THRESHOLD = 1 << 16;

/** Buffers output lines and hands them to the sink in large chunks. */
class LineWriter {
  readonly #sink: (chunk: string) => void;
  #lines: string[] = [];
  #pending = 0;

  constructor(sink: (chunk: string) => void) {
    this.#sink = sink;
  }

  writeLine(text: string): void {
    this.#lines.push(text);
    this.#pending += text.length + 1;
    if (this.#pending >= OUTPUT_FLUSH_THRESHOLD) this.flush();
  }

  flush(): void {
    if (this.#lines.length === 0) return;
    this.#lines.push('');
    this.#sink(this.#lines.join('\n'));
    this.#lines = [];
    this.#pending = 0;
  }
}

/** Interprets the command stream: a capacity header, then one command per line. */
class CommandProcessor {
  readonly #out: LineWriter;
  #cache: LruCache<string, string> | null = null;

  constructor(out: LineWriter) {
    this.#out = out;
  }

  processLine(rawLine: string): void {
    const line = rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine;
    if (this.#cache === null) {
      this.#cache = new LruCache(parseCapacity(line));
      return;
    }
    this.#execute(this.#cache, line);
  }

  #execute(cache: LruCache<string, string>, line: string): void {
    const firstSpace = line.indexOf(' ');
    const command = firstSpace < 0 ? line : line.slice(0, firstSpace);
    switch (command) {
      case 'SET': {
        const secondSpace = line.indexOf(' ', firstSpace + 1);
        if (secondSpace < 0) return;
        cache.set(line.slice(firstSpace + 1, secondSpace), line.slice(secondSpace + 1));
        break;
      }
      case 'GET': {
        if (firstSpace < 0) return;
        this.#out.writeLine(cache.get(line.slice(firstSpace + 1)) ?? 'NULL');
        break;
      }
      case 'DEL': {
        if (firstSpace < 0) return;
        this.#out.writeLine(cache.delete(line.slice(firstSpace + 1)) ? '1' : '0');
        break;
      }
      case 'SIZE':
        this.#out.writeLine(String(cache.size));
        break;
      default:
        // Blank or unrecognised lines are ignored.
        break;
    }
  }
}

function parseCapacity(header: string): number {
  const text = header.trim();
  if (!/^[+-]?\d+$/.test(text)) throw new Error(`invalid capacity: ${JSON.stringify(header)}`);
  return Number.parseInt(text, 10);
}

async function main(): Promise<void> {
  const out = new LineWriter((chunk) => process.stdout.write(chunk, 'latin1'));
  const processor = new CommandProcessor(out);

  process.stdin.setEncoding('latin1');
  let carry = '';
  for await (const chunk of process.stdin as AsyncIterable<string>) {
    const text = carry + chunk;
    let start = 0;
    let end: number;
    while ((end = text.indexOf('\n', start)) >= 0) {
      processor.processLine(text.slice(start, end));
      start = end + 1;
    }
    carry = text.slice(start);
  }
  if (carry.length > 0) processor.processLine(carry);
  out.flush();
}

await main();
